	fields(value, ["name", "slug"]);
	return {
		...(create || value.name !== undefined
			? { name: organizationName(value.name) }
			: {}),
		...(create || value.slug !== undefined
			? { slug: organizationSlug(value.slug) }
			: {}),
	};
