			else if (returned.status === "FORBIDDEN") code = "forbidden";
			else if (returned.status === "BAD_REQUEST") code = "invalid-input";
			apiFailure(code);
		}
	});
	return {
		plugin,
		before,
		after,
		config,
		onAPIError: {
			onError(error: unknown) {
				if (error instanceof APIError) throw error;
				safeFailure(error);
			},
		},
	};
}

import { drizzle } from "drizzle-orm/node-postgres";
import { Pool } from "pg";
// Dedicated lazy native-auth pool: bounds actual I/O without changing the shared
// application pool. Construction validates no network/data and never migrates.
export function createBoundedOrganizationAuthDatabase<
	TSchema extends Record<string, unknown>,
>(connectionString: string, schema: TSchema) {
	const pool = new Pool({
		connectionString,
		options: "-c statement_timeout=5000 -c lock_timeout=2000",
		connectionTimeoutMillis: 5000,
	});
	// pg removes a failed idle client; discard its raw diagnostic rather than emitting it.
	pool.on("error", () => {});
	return { db: drizzle(pool, { schema }), close: () => pool.end() };
}

